// Combinar nichos activos con títulos existentes para anti-canibalización
const activeNiches = $('Filtrar Nichos Activos').all().map(i => i.json);
const existingRows = $('Read Titulos Existentes').all().map(i => i.json);

// Crear set de títulos existentes (normalizado)
const existingTitles = new Set(
  existingRows
    .filter(r => r.TITLE)
    .map(r => r.TITLE.toLowerCase().trim())
);

// Contar PENDING por nicho
const pendingByNiche = {};
existingRows.filter(r => r.STATUS === 'PENDING').forEach(r => {
  pendingByNiche[r.NICHE] = (pendingByNiche[r.NICHE] || 0) + 1;
});

// Filtrar nichos que necesitan más títulos (< 20 pending)
const nichesNeedingTitles = activeNiches.filter(n =>
  (pendingByNiche[n.NICHE_ID] || 0) < 20
);

if (nichesNeedingTitles.length === 0) {
  return [{ json: { _skip: true, reason: 'Todos los nichos tienen suficientes pending' } }];
}

// Obtener el último ROW_NUMBER para inserción correcta
const lastRowNumber = existingRows.reduce((max, r) => {
  const n = parseInt(r.ROW_NUMBER || '1');
  return n > max ? n : max;
}, 1);

return nichesNeedingTitles.map(niche => ({
  json: {
    niche: niche.NICHE_ID,
    displayName: niche.DISPLAY_NAME,
    language: niche.LANGUAGE || 'es',
    blogId: niche.BLOG_ID || '<!-- BLOG_ID -->',
    affiliateCategory: niche.AFFILIATE_CATEGORY || 'general',
    existingTitles: Array.from(existingTitles),
    lastRowNumber,
    pendingCount: pendingByNiche[niche.NICHE_ID] || 0
  }
}));

