const res = $('Generar Títulos con DeepSeek').item.json;
const prev = $('Preparar Generación por Nicho').item.json;

let titlesData;
try {
  const content = res.choices[0].message.content;
  // Limpiar posibles markdown fences
  const clean = content.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```\s*$/i,'').trim();
  titlesData = JSON.parse(clean);
} catch(e) {
  throw new Error('DeepSeek no retornó JSON válido: ' + JSON.stringify(res).substring(0,200));
}

const titles = titlesData.titles || [];
if (titles.length === 0) throw new Error('DeepSeek retornó lista de títulos vacía');

const existingSet = new Set(prev.existingTitles);
let rowNum = prev.lastRowNumber + 1;

// Construir filas para Google Sheets
const rows = [];
for (const t of titles) {
  if (!t.title || existingSet.has(t.title.toLowerCase().trim())) continue;
  rows.push([
    rowNum,           // ROW_NUMBER
    'PENDING',        // STATUS
    'FALSE',          // LOCK
    '',               // LOCK_TIMESTAMP
    t.title,          // TITLE
    prev.niche,       // NICHE
    t.keywords || '', // KEYWORDS
    prev.blogId,      // BLOG_ID
    prev.language,    // LANGUAGE
    t.priority || 3,  // PRIORITY
    '', '', '', '', '', '', // HTML_CONTENT, TOKENS_USED, GENERATED_AT, PUBLISHED_URL, POST_ID, PUBLISHED_AT
    'FALSE', 'FALSE', 'FALSE', // AFFILIATE_INJECTED, SOCIAL_DISTRIBUTED, INTERLINKS_ADDED
    '', '0'           // ERROR_MESSAGE, RETRY_COUNT
  ]);
  rowNum++;
}

if (rows.length === 0) throw new Error('Todos los títulos generados ya existen en el pipeline');

return rows.map(row => ({ json: { _row: row, _niche: prev.niche, _count: rows.length } }));
